import torch
import triton
import triton.language as tl
from task import input_t, output_t


# =============================================================================
# Persistent one-threadblock-per-matrix fused Householder QR megakernel.
#
# Two backends:
#  * Triton unblocked tile kernel for tiny n (<= 64): whole matrix in registers.
#  * CUDA full-matrix-in-smem kernel for small/medium n that fits 227KB smem:
#    one thread block factors one matrix entirely on-chip (read once, write
#    once). Thread `t` owns column `t` (column-major smem), so the trailing
#    Householder update A[:,j] -= tau*v*(v.A[:,j]) is a per-thread sequential
#    dot product with no cross-thread reduction; only the pivot column norm
#    needs a block reduction. Output is packed LAPACK/geqrf layout:
#       H = R on/above diag, reflectors v (v[k]=1 implicit) below; tau[k] coef.
#    Q = householder_product(H, tau), R = triu(H): matches torch.geqrf.
# =============================================================================


# ----------------------------- Triton (tiny n) -------------------------------
@triton.jit
def _qr_unblocked_kernel(
    A_ptr, TAU_ptr, B,
    N: tl.constexpr, BN: tl.constexpr,
):
    pid = tl.program_id(0)
    num_programs = tl.num_programs(0)
    row = tl.arange(0, BN)
    col = tl.arange(0, BN)
    valid_r = row < N
    valid_c = col < N
    mask2d = valid_r[:, None] & valid_c[None, :]
    b = pid
    while b < B:
        base = b * N * N
        a = tl.load(A_ptr + base + row[:, None] * N + col[None, :],
                    mask=mask2d, other=0.0)
        for k in range(0, N - 1):
            ak = tl.sum(tl.where(col[None, :] == k, a, 0.0), axis=1)
            below = row >= k
            xk = tl.where(below, ak, 0.0)
            alpha = tl.sum(tl.where(row == k, ak, 0.0))
            normsq = tl.sum(xk * xk)
            xnorm = tl.sqrt(normsq)
            sign = tl.where(alpha >= 0.0, 1.0, -1.0)
            beta = -sign * xnorm
            safe = xnorm > 0.0
            tau = tl.where(safe, (beta - alpha) / beta, 0.0)
            denom = alpha - beta
            inv_denom = tl.where(safe & (denom != 0.0), 1.0 / denom, 0.0)
            v = xk * inv_denom
            v = tl.where(row == k, 1.0, v)
            v = tl.where(below, v, 0.0)
            w = tl.sum(v[:, None] * a, axis=0)
            colmask = col >= k
            a = tl.where(colmask[None, :], a - tau * (v[:, None] * w[None, :]), a)
            colk_sel = col[None, :] == k
            new_colk = tl.where(row[:, None] == k, beta,
                                tl.where(row[:, None] > k, v[:, None], a))
            a = tl.where(colk_sel, new_colk, a)
            tl.store(TAU_ptr + b * N + k, tau)
        tl.store(TAU_ptr + b * N + (N - 1), 0.0)
        tl.store(A_ptr + base + row[:, None] * N + col[None, :], a, mask=mask2d)
        b += num_programs


def _qr_triton(a: torch.Tensor) -> output_t:
    B, n, _ = a.shape
    H = a.clone()
    tau = torch.empty((B, n), device=a.device, dtype=torch.float32)
    BN = triton.next_power_of_2(n)
    num_sms = torch.cuda.get_device_properties(a.device).multi_processor_count
    grid = (min(num_sms, B),)
    _qr_unblocked_kernel[grid](H, tau, B, N=n, BN=BN)
    return H, tau


# --------------------------- CUDA full-in-smem -------------------------------
_CUDA_SRC = r"""
#include <cstdint>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

// One thread block per matrix. The full n x n matrix is held in shared memory
// (column-major: As[r + c*n]). Thread t owns column t (and t + blockDim, ...).
// Right-looking unblocked Householder; writes packed (H, tau).
//
// Templated thread count TPB; n passed at runtime (n <= TPB or strided).
template <int TPB>
__global__ void qr_smem_kernel(const float* __restrict__ A,
                               float* __restrict__ H,
                               float* __restrict__ tau,
                               int B, int n) {
    extern __shared__ float smem[];
    float* As = smem;             // n*n floats
    float* red = smem + n * n;    // TPB floats for reductions
    float* vcol = red + TPB;      // n floats: current reflector v (rows)
    float* sval = vcol + n;       // small scalars: [0]=beta,[1]=tau,[2]=invdenom

    const int tid = threadIdx.x;

    for (int b = blockIdx.x; b < B; b += gridDim.x) {
        const float* Ab = A + (size_t)b * n * n;   // row-major input (b,r,c)
        float* Hb = H + (size_t)b * n * n;
        float* taub = tau + (size_t)b * n;

        // Load matrix into smem, transposing row-major -> column-major.
        // input element (r,c) at Ab[r*n + c] -> As[r + c*n].
        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n;
            int c = idx % n;
            As[c * n + r] = Ab[r * n + c];
        }
        __syncthreads();

        for (int k = 0; k < n - 1; ++k) {
            // --- pivot column norm over rows >= k ---
            float partial = 0.f;
            for (int r = k + tid; r < n; r += TPB) {
                float x = As[k * n + r];
                partial += x * x;
            }
            red[tid] = partial;
            __syncthreads();
            for (int s = TPB / 2; s > 0; s >>= 1) {
                if (tid < s) red[tid] += red[tid + s];
                __syncthreads();
            }
            // thread 0 computes beta/tau/invdenom
            if (tid == 0) {
                float normsq = red[0];
                float xnorm = sqrtf(normsq);
                float alpha = As[k * n + k];
                float beta = (alpha >= 0.f) ? -xnorm : xnorm;
                float tval, invden;
                if (xnorm > 0.f && (alpha - beta) != 0.f) {
                    tval = (beta - alpha) / beta;
                    invden = 1.f / (alpha - beta);
                } else {
                    tval = 0.f;
                    invden = 0.f;
                    beta = alpha;  // no reflection
                }
                sval[0] = beta;
                sval[1] = tval;
                sval[2] = invden;
            }
            __syncthreads();
            float beta = sval[0];
            float tval = sval[1];
            float invden = sval[2];

            // build v into vcol: v[k]=1, v[r]=As[k,r]*invden for r>k, else 0
            for (int r = tid; r < n; r += TPB) {
                float vv;
                if (r < k) vv = 0.f;
                else if (r == k) vv = 1.f;
                else vv = As[k * n + r] * invden;
                vcol[r] = vv;
            }
            __syncthreads();

            // trailing update: each thread owns columns j (strided), j > k
            for (int j = k + 1 + tid; j < n; j += TPB) {
                float* Acol = As + j * n;
                // w = v . A[:,j]  over rows >= k
                float w = 0.f;
                #pragma unroll 4
                for (int r = k; r < n; ++r) w += vcol[r] * Acol[r];
                float tw = tval * w;
                #pragma unroll 4
                for (int r = k; r < n; ++r) Acol[r] -= tw * vcol[r];
            }
            __syncthreads();

            // pack column k: diag = beta, below = v ; tau[k] = tval
            for (int r = tid; r < n; r += TPB) {
                if (r == k) As[k * n + r] = beta;
                else if (r > k) As[k * n + r] = vcol[r];
            }
            if (tid == 0) taub[k] = tval;
            __syncthreads();
        }
        if (tid == 0) taub[n - 1] = 0.f;
        __syncthreads();

        // write H back row-major: Hb[r*n+c] = As[c*n+r]
        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n;
            int c = idx % n;
            Hb[r * n + c] = As[c * n + r];
        }
        __syncthreads();
    }
}

void qr_smem_launch(int64_t A_ptr, int64_t H_ptr, int64_t tau_ptr,
                    int B, int n, int grid) {
    const float* A = reinterpret_cast<const float*>(A_ptr);
    float* H = reinterpret_cast<float*>(H_ptr);
    float* tau = reinterpret_cast<float*>(tau_ptr);
    const int TPB = 256;
    size_t shbytes = ((size_t)n * n + TPB + n + 4) * sizeof(float);
    cudaFuncSetAttribute(qr_smem_kernel<TPB>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)shbytes);
    qr_smem_kernel<TPB><<<grid, TPB, shbytes>>>(A, H, tau, B, n);
}

// ---------------------------------------------------------------------------
// Global-memory unblocked Householder, one block per matrix. Matrix held in a
// COLUMN-MAJOR global scratch (Acm[b*n*n + c*n + r]); only the current
// reflector and reductions live in smem. BLAS-2 trailing update over global
// columns, but the whole batch is processed in parallel (grid blocks looping
// over matrices). For n that does not fit fully in smem (n > ~224).
template <int TPB>
__global__ void qr_global_kernel(const float* __restrict__ A,  // row-major in
                                 float* __restrict__ Acm,      // col-major scratch
                                 float* __restrict__ H,        // row-major out
                                 float* __restrict__ tau,
                                 int B, int n) {
    extern __shared__ float smem[];
    float* red = smem;            // TPB
    float* vcol = red + TPB;      // n: reflector v (rows)
    float* sval = vcol + n;       // scalars

    const int tid = threadIdx.x;

    for (int b = blockIdx.x; b < B; b += gridDim.x) {
        const float* Ab = A + (size_t)b * n * n;
        float* Acmb = Acm + (size_t)b * n * n;
        float* Hb = H + (size_t)b * n * n;
        float* taub = tau + (size_t)b * n;

        // transpose row-major -> column-major scratch
        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n;
            int c = idx % n;
            Acmb[c * n + r] = Ab[r * n + c];
        }
        __syncthreads();

        for (int k = 0; k < n - 1; ++k) {
            float* colk = Acmb + (size_t)k * n;
            float partial = 0.f;
            for (int r = k + tid; r < n; r += TPB) {
                float x = colk[r];
                partial += x * x;
            }
            red[tid] = partial;
            __syncthreads();
            for (int s = TPB / 2; s > 0; s >>= 1) {
                if (tid < s) red[tid] += red[tid + s];
                __syncthreads();
            }
            if (tid == 0) {
                float xnorm = sqrtf(red[0]);
                float alpha = colk[k];
                float beta = (alpha >= 0.f) ? -xnorm : xnorm;
                float tval, invden;
                if (xnorm > 0.f && (alpha - beta) != 0.f) {
                    tval = (beta - alpha) / beta;
                    invden = 1.f / (alpha - beta);
                } else { tval = 0.f; invden = 0.f; beta = alpha; }
                sval[0] = beta; sval[1] = tval; sval[2] = invden;
            }
            __syncthreads();
            float beta = sval[0], tval = sval[1], invden = sval[2];

            for (int r = tid; r < n; r += TPB) {
                float vv;
                if (r < k) vv = 0.f;
                else if (r == k) vv = 1.f;
                else vv = colk[r] * invden;
                vcol[r] = vv;
            }
            __syncthreads();

            for (int j = k + 1 + tid; j < n; j += TPB) {
                float* Acol = Acmb + (size_t)j * n;
                float w = 0.f;
                for (int r = k; r < n; ++r) w += vcol[r] * Acol[r];
                float tw = tval * w;
                for (int r = k; r < n; ++r) Acol[r] -= tw * vcol[r];
            }
            __syncthreads();

            for (int r = tid; r < n; r += TPB) {
                if (r == k) colk[r] = beta;
                else if (r > k) colk[r] = vcol[r];
            }
            if (tid == 0) taub[k] = tval;
            __syncthreads();
        }
        if (tid == 0) taub[n - 1] = 0.f;
        __syncthreads();

        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n;
            int c = idx % n;
            Hb[r * n + c] = Acmb[c * n + r];
        }
        __syncthreads();
    }
}

void qr_global_launch(int64_t A_ptr, int64_t Acm_ptr, int64_t H_ptr,
                      int64_t tau_ptr, int B, int n, int grid) {
    const float* A = reinterpret_cast<const float*>(A_ptr);
    float* Acm = reinterpret_cast<float*>(Acm_ptr);
    float* H = reinterpret_cast<float*>(H_ptr);
    float* tau = reinterpret_cast<float*>(tau_ptr);
    const int TPB = 256;
    size_t shbytes = ((size_t)TPB + n + 4) * sizeof(float);
    qr_global_kernel<TPB><<<grid, TPB, shbytes>>>(A, Acm, H, tau, B, n);
}

// ===========================================================================
// Blocked compact-WY Householder QR, ONE BLOCK PER MATRIX. The active column
// panel lives in shared memory; the trailing block is updated with a
// BLAS-3 (I - V T^T V^T) sweep that reuses V and a trailing chunk from smem.
// Matrix held in a column-major global scratch (Acm[b*n*n + c*n + r]); H is
// written row-major in geqrf packing.
//
// NB  = panel width (reflectors per block step)
// CT  = trailing-column chunk width processed per smem tile
// ===========================================================================
template <int TPB, int NB, int CT>
__global__ void qr_blocked_kernel(const float* __restrict__ A,
                                  float* __restrict__ Acm,
                                  float* __restrict__ H,
                                  float* __restrict__ tau,
                                  int B, int n) {
    extern __shared__ float smem[];
    float* Ps   = smem;                 // n * NB  : current panel (col-major)
    float* Ts   = Ps + (size_t)n * NB;  // NB * NB : T (col-major: Ts[i + l*NB])
    float* Cs   = Ts + NB * NB;         // n * CT  : trailing chunk (col-major)
    float* Ws   = Cs + (size_t)n * CT;  // 2*NB*CT : W and W' workspace
    float* taus = Ws + 2 * NB * CT;     // NB      : panel tau values
    float* red  = taus + NB;            // REDSZ   : reductions / warp partials
    const int REDSZ = (8 * NB > TPB) ? 8 * NB : TPB;
    float* pww  = red + REDSZ;          // NB      : panel-update w (tau*w) values
    float* sval = pww + NB;             // scalars

    const int tid = threadIdx.x;

    for (int b = blockIdx.x; b < B; b += gridDim.x) {
        const float* Ab = A + (size_t)b * n * n;
        float* Acmb = Acm + (size_t)b * n * n;
        float* Hb = H + (size_t)b * n * n;
        float* taub = tau + (size_t)b * n;

        // row-major -> column-major scratch
        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n, c = idx % n;
            Acmb[c * n + r] = Ab[r * n + c];
        }
        __syncthreads();

        for (int p = 0; p < n; p += NB) {
            int nb = NB; if (p + nb > n) nb = n - p;

            // ---- load panel Acm[:, p:p+nb] into Ps (full height) ----
            for (int idx = tid; idx < n * nb; idx += TPB) {
                int j = idx / n, r = idx % n;
                Ps[(size_t)j * n + r] = Acmb[(size_t)(p + j) * n + r];
            }
            __syncthreads();

            // ---- panel factorization (unblocked, in smem) ----
            for (int j = 0; j < nb; ++j) {
                int c = p + j;
                float* pj = Ps + (size_t)j * n;       // panel column j
                // norm over rows >= c
                float partial = 0.f;
                for (int r = c + tid; r < n; r += TPB) {
                    float x = pj[r]; partial += x * x;
                }
                red[tid] = partial; __syncthreads();
                for (int s = TPB / 2; s > 0; s >>= 1) {
                    if (tid < s) red[tid] += red[tid + s];
                    __syncthreads();
                }
                if (tid == 0) {
                    float xnorm = sqrtf(red[0]);
                    float alpha = pj[c];
                    float beta = (alpha >= 0.f) ? -xnorm : xnorm;
                    float tval, invden;
                    if (xnorm > 0.f && (alpha - beta) != 0.f) {
                        tval = (beta - alpha) / beta;
                        invden = 1.f / (alpha - beta);
                    } else { tval = 0.f; invden = 0.f; beta = alpha; }
                    sval[0] = beta; sval[1] = tval; sval[2] = invden;
                }
                __syncthreads();
                float beta = sval[0], tval = sval[1], invden = sval[2];
                // normalize reflector for rows r>c (scale by invden); leave
                // rows r<c (R values) untouched; row c set to 1 transiently for
                // the panel update, restored to beta afterwards.
                for (int r = c + 1 + tid; r < n; r += TPB) pj[r] = pj[r] * invden;
                __syncthreads();
                if (tid == 0) { pj[c] = 1.f; taus[j] = tval; }
                __syncthreads();
                // apply reflector to ALL remaining panel columns jj>j at once.
                // Batched: each thread accumulates partial dots for every jj in
                // registers over its row strip (one pass), warp-reduces, then a
                // single block sync produces w[jj]; finally update all columns.
                // This collapses (nb-j) block reductions into ~2 syncs.
                int ntrail = nb - (j + 1);
                if (ntrail > 0) {
                    const int lane = tid & 31;
                    const int warp = tid >> 5;
                    const int NWARP = TPB / 32;
                    float pw[NB];
                    #pragma unroll
                    for (int t = 0; t < NB; ++t) pw[t] = 0.f;
                    for (int r = c + tid; r < n; r += TPB) {
                        float vr = pj[r];
                        for (int t = 0; t < ntrail; ++t)
                            pw[t] += vr * Ps[(size_t)(j + 1 + t) * n + r];
                    }
                    // warp-reduce each pw[t]; warp leaders -> red[warp*NB + t]
                    for (int t = 0; t < ntrail; ++t) {
                        float v = pw[t];
                        #pragma unroll
                        for (int o = 16; o > 0; o >>= 1)
                            v += __shfl_down_sync(0xffffffff, v, o);
                        if (lane == 0) red[warp * NB + t] = v;
                    }
                    __syncthreads();
                    // thread t sums NWARP warp-partials -> tau*w[t] in pww
                    if (tid < ntrail) {
                        float w = 0.f;
                        for (int wi = 0; wi < NWARP; ++wi) w += red[wi * NB + tid];
                        pww[tid] = tval * w;  // tau*w
                    }
                    __syncthreads();
                    // update all trailing panel columns
                    for (int t = 0; t < ntrail; ++t) {
                        float tw = pww[t];
                        float* pjj = Ps + (size_t)(j + 1 + t) * n;
                        for (int r = c + tid; r < n; r += TPB)
                            pjj[r] -= tw * pj[r];
                    }
                    __syncthreads();
                }
                // store beta (R diagonal) back into panel column j at row c
                if (tid == 0) pj[c] = beta;
                __syncthreads();
            }
            // restore implicit unit diagonal of V for the WY math: we need
            // V with V[c,j]=1. Currently pj[c]=beta. Use a separate read:
            // build T using V where diag=1. We'll treat Ps diag specially.

            // ---- build T (compact WY) ----
            // V[r,i] = (r==p+i)?1 : (r>p+i? Ps[i*n+r] : 0).  beta sits on diag
            // in Ps so we must override it to 1 when used as V.
            // T[i,i]=taus[i]; for l>i: T[i,l] = -taus[l]*sum_{m<=l-1}... use
            // column recurrence: for each l, z[i]=V[:,i]^T V[:,l] (i<l), then
            // T[0:l,l] = -taus[l]* T[0:l,0:l] @ z.
            // init diagonal
            for (int i = tid; i < nb; i += TPB) Ts[(size_t)i + (size_t)i * NB] = taus[i];
            __syncthreads();
            for (int l = 1; l < nb; ++l) {
                int cl = p + l;
                // z[i] = V[:,i]^T V[:,l] for all i<l, computed in ONE fused pass
                // (rows r>=cl, with V[cl,l]=1): each thread accumulates partial
                // z[i] for every i in registers, warp-shuffle reduce, 1 sync.
                // Replaces l block-reductions with ~2 syncs.
                const float* Vl = Ps + (size_t)l * n;
                const int lane = tid & 31, warp = tid >> 5;
                const int NWARP = TPB / 32;
                float pz[NB];
                #pragma unroll
                for (int t = 0; t < NB; ++t) pz[t] = 0.f;
                for (int r = cl + tid; r < n; r += TPB) {
                    float vl = (r == cl) ? 1.f : Vl[r];
                    for (int i = 0; i < l; ++i)
                        pz[i] += Ps[(size_t)i * n + r] * vl;
                }
                for (int i = 0; i < l; ++i) {
                    float v = pz[i];
                    #pragma unroll
                    for (int o = 16; o > 0; o >>= 1)
                        v += __shfl_down_sync(0xffffffff, v, o);
                    if (lane == 0) red[warp * NB + i] = v;
                }
                __syncthreads();
                // thread i sums NWARP warp-partials -> z[i] in Ws[i]
                if (tid < l) {
                    float zz = 0.f;
                    for (int wi = 0; wi < NWARP; ++wi) zz += red[wi * NB + tid];
                    Ws[tid] = zz;
                }
                __syncthreads();
                // T[0:l,l] = -taus[l] * (T[0:l,0:l] @ z)
                float tl = taus[l];
                for (int i = tid; i < l; i += TPB) {
                    float acc = 0.f;
                    for (int m = i; m < l; ++m)  // T upper-tri: T[i,m], m>=i
                        acc += Ts[(size_t)i + (size_t)m * NB] * Ws[m];
                    Ts[(size_t)i + (size_t)l * NB] = -tl * acc;
                }
                __syncthreads();
            }

            // ---- trailing update: cols [p+nb, n) in chunks of CT ----
            int tstart = p + nb;
            for (int g0 = tstart; g0 < n; g0 += CT) {
                int ct = CT; if (g0 + ct > n) ct = n - g0;
                // load chunk Acm[:, g0:g0+ct] into Cs
                for (int idx = tid; idx < n * ct; idx += TPB) {
                    int g = idx / n, r = idx % n;
                    Cs[(size_t)g * n + r] = Acmb[(size_t)(g0 + g) * n + r];
                }
                __syncthreads();
                // W[i,g] = sum_{r>=p} V[r,i] * Cs[r,g]   (i<nb, g<ct).  G-tile by
                // 2: one i, two adjacent g -> load V[r,i] once, reuse across the
                // two chunk columns (halves the Vi smem traffic). Diagonal term
                // V[ci,i]=1 handled separately.
                int ng2 = (ct + 1) / 2;
                for (int idx = tid; idx < nb * ng2; idx += TPB) {
                    int gt = idx / nb, i = idx % nb;
                    int g0 = gt * 2;
                    bool hg1 = (g0 + 1 < ct);
                    int ci = p + i;
                    const float* Vi = Ps + (size_t)i * n;
                    const float* C0 = Cs + (size_t)g0 * n;
                    const float* C1 = Cs + (size_t)(g0 + 1) * n;
                    float s0 = C0[ci];                 // V[ci,i]=1 term
                    float s1 = hg1 ? C1[ci] : 0.f;
                    float t0 = 0.f, t1 = 0.f;
                    int r = ci + 1;
                    for (; r + 1 < n; r += 2) {
                        float v0 = Vi[r], v1 = Vi[r + 1];
                        s0 += v0 * C0[r];     t0 += v1 * C0[r + 1];
                        if (hg1) { s1 += v0 * C1[r]; t1 += v1 * C1[r + 1]; }
                    }
                    for (; r < n; ++r) {
                        float v0 = Vi[r];
                        s0 += v0 * C0[r];
                        if (hg1) s1 += v0 * C1[r];
                    }
                    Ws[(size_t)i + (size_t)g0 * NB] = s0 + t0;
                    if (hg1) Ws[(size_t)i + (size_t)(g0 + 1) * NB] = s1 + t1;
                }
                __syncthreads();
                // W' = T^T @ W :  W'[i,g] = sum_{l<=i} T[l,i] W[l,g]
                // do in place using a temp per (i,g): read all W[l,g] l<=i
                // Store into Cs-free? Need separate buffer; reuse red? Instead
                // compute into registers by reading Ws then overwrite Ws after
                // a barrier. Use a second pass writing to taus? Too small.
                // Allocate W' in the same Ws by computing top-down is unsafe.
                // Simplest: compute W'[i,g] reading Ws (old), write to Cs top
                // rows? No. Use a small stack array since nb<=NB known const.
                {
                    // each thread handles some (i,g); reads Ws[l,g] for l<=i.
                    // Ws is read-only here; we write results to a shadow in
                    // the unused tail of Cs? Cs is n*CT, we only use n rows.
                    // Use Ts is busy. We'll write W' into Ps? Ps is V, busy.
                    // Allocate via local then sync-store: two-phase.
                }
                // Two-phase T^T W using register temp + barrier:
                // phase 1: each (i,g) computes wp into a per-thread value and
                // stashes into red is too small. Instead loop g-chunks small:
                // We compute W' in place safely because W'[i] depends on W[l<=i]
                // -> process i from high to low won't help (needs lower l).
                // Use a separate smem region: extend Ws to 2*NB*CT.
                for (int idx = tid; idx < nb * ct; idx += TPB) {
                    int g = idx / nb, i = idx % nb;
                    float acc = 0.f;
                    for (int l = 0; l <= i; ++l)
                        acc += Ts[(size_t)l + (size_t)i * NB] * Ws[(size_t)l + (size_t)g * NB];
                    // stash in second half
                    Ws[(size_t)NB * CT + (size_t)i + (size_t)g * NB] = acc;
                }
                __syncthreads();
                // Cs[r,g] -= sum_i V[r,i] * W'[i,g]   (r>=p).  Register-tile
                // over g (4 cols/thread): load V[r,i] once, reuse across the
                // g-tile -> 4x fewer strided Ps[i*n+r] loads.
                const float* Wp = Ws + (size_t)NB * CT;
                int nrows = n - p;          // active rows r in [p, n)
                int ng4 = (ct + 3) / 4;     // number of g-tiles of width 4
                for (int idx = tid; idx < nrows * ng4; idx += TPB) {
                    int gt = idx / nrows;
                    int rr = idx % nrows;
                    int r = p + rr;
                    int g0c = gt * 4;
                    float acc0 = 0.f, acc1 = 0.f, acc2 = 0.f, acc3 = 0.f;
                    bool h1 = (g0c + 1 < ct), h2 = (g0c + 2 < ct), h3 = (g0c + 3 < ct);
                    for (int i = 0; i < nb; ++i) {
                        int ci = p + i;
                        if (r < ci) break;
                        float vi = (r == ci) ? 1.f : Ps[(size_t)i * n + r];
                        const float* Wpi = Wp + i;
                        acc0 += vi * Wpi[(size_t)(g0c) * NB];
                        if (h1) acc1 += vi * Wpi[(size_t)(g0c + 1) * NB];
                        if (h2) acc2 += vi * Wpi[(size_t)(g0c + 2) * NB];
                        if (h3) acc3 += vi * Wpi[(size_t)(g0c + 3) * NB];
                    }
                    Cs[(size_t)(g0c) * n + r] -= acc0;
                    if (h1) Cs[(size_t)(g0c + 1) * n + r] -= acc1;
                    if (h2) Cs[(size_t)(g0c + 2) * n + r] -= acc2;
                    if (h3) Cs[(size_t)(g0c + 3) * n + r] -= acc3;
                }
                __syncthreads();
                // write chunk back to global
                for (int idx = tid; idx < n * ct; idx += TPB) {
                    int g = idx / n, r = idx % n;
                    Acmb[(size_t)(g0 + g) * n + r] = Cs[(size_t)g * n + r];
                }
                __syncthreads();
            }

            // ---- write panel back to global scratch (R + reflectors) ----
            for (int idx = tid; idx < n * nb; idx += TPB) {
                int j = idx / n, r = idx % n;
                Acmb[(size_t)(p + j) * n + r] = Ps[(size_t)j * n + r];
            }
            // store tau for this panel
            for (int j = tid; j < nb; j += TPB) taub[p + j] = taus[j];
            __syncthreads();
        }
        if (tid == 0) { /* last tau handled per-panel */ }

        // write H row-major from column-major scratch
        for (int idx = tid; idx < n * n; idx += TPB) {
            int r = idx / n, c = idx % n;
            Hb[r * n + c] = Acmb[c * n + r];
        }
        __syncthreads();
    }
}

template <int TPB, int NB, int CT>
static void launch_blocked(const float* A, float* Acm, float* H, float* tau,
                           int B, int n, int grid) {
    const int REDSZ = (8 * NB > TPB) ? 8 * NB : TPB;
    size_t fcount = (size_t)n * NB + NB * NB + (size_t)n * CT
                    + 2 * NB * CT + NB + REDSZ + NB + 8;
    size_t shbytes = fcount * sizeof(float);
    cudaFuncSetAttribute(qr_blocked_kernel<TPB, NB, CT>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize,
                         (int)shbytes);
    qr_blocked_kernel<TPB, NB, CT><<<grid, TPB, shbytes>>>(A, Acm, H, tau, B, n);
}

void qr_blocked_launch(int64_t A_ptr, int64_t Acm_ptr, int64_t H_ptr,
                       int64_t tau_ptr, int B, int n, int grid, int cfg) {
    const float* A = reinterpret_cast<const float*>(A_ptr);
    float* Acm = reinterpret_cast<float*>(Acm_ptr);
    float* H = reinterpret_cast<float*>(H_ptr);
    float* tau = reinterpret_cast<float*>(tau_ptr);
    const int TPB = 256;
    switch (cfg) {
        case 0: launch_blocked<TPB, 32, 64>(A, Acm, H, tau, B, n, grid); break;
        case 1: launch_blocked<TPB, 48, 48>(A, Acm, H, tau, B, n, grid); break;
        case 2: launch_blocked<TPB, 64, 32>(A, Acm, H, tau, B, n, grid); break;
        case 3: launch_blocked<TPB, 64, 24>(A, Acm, H, tau, B, n, grid); break;
        case 4: launch_blocked<TPB, 32, 96>(A, Acm, H, tau, B, n, grid); break;
        case 5: launch_blocked<TPB, 16, 128>(A, Acm, H, tau, B, n, grid); break;
        case 6: launch_blocked<TPB, 16, 32>(A, Acm, H, tau, B, n, grid); break;
        case 7: launch_blocked<TPB, 16, 16>(A, Acm, H, tau, B, n, grid); break;
        case 8: launch_blocked<TPB, 24, 24>(A, Acm, H, tau, B, n, grid); break;
        case 9: launch_blocked<TPB, 16, 64>(A, Acm, H, tau, B, n, grid); break;
        case 10: launch_blocked<TPB, 8, 64>(A, Acm, H, tau, B, n, grid); break;
        case 11: launch_blocked<TPB, 16, 48>(A, Acm, H, tau, B, n, grid); break;
        default: launch_blocked<TPB, 32, 64>(A, Acm, H, tau, B, n, grid); break;
    }
}

// ===========================================================================
// MULTI-CTA COOPERATIVE blocked Householder QR for LARGE n (n > 1024) where the
// matrix does not fit in shared memory and the batch is tiny (2-8 matrices), so
// one-block-per-matrix would idle ~140 of 148 SMs. ALL CTAs in a single
// persistent grid cooperate on ONE matrix at a time:
//
//   for each panel p (width NB):
//     [block 0] factor panel cols [p,p+nb) (unblocked Householder, BLAS-2 over
//               GLOBAL memory -- no full-height panel in smem), build compact-WY
//               T (NB x NB) in a tiny global buffer, write tau.
//     [GRID BARRIER]
//     [all blocks] grid-stride over trailing columns g in [p+nb, n): apply the
//               block reflector  C[:,g] -= V (T^T (V^T C[:,g]))  -- each trailing
//               column is independent, so NO cross-CTA reduction is needed.
//     [GRID BARRIER]
//
// Cross-CTA sync is a hand-rolled reusable sense-reversal atomic barrier (plain
// <<<grid,TPB>>> launch on the default execution queue, graph-capture safe). The grid is
// sized by the host to <= one-wave occupancy so every block is co-resident
// (deadlock-free). Reflectors V live IN PLACE below the diagonal of Acm; T lives
// in a small global scratch. Output is geqrf packing (R on/above diag,
// reflectors below, tau separate). Rank-deficiency guard: xnorm==0 -> tau=0.
// ===========================================================================

// Reusable grid barrier (sense reversal). g_bar[0]=arrival counter, g_bar[1]=
// sense. PRECONDITION: gridSize <= resident-CTA capacity (host enforces).
__device__ __forceinline__ void coop_grid_barrier(
        unsigned int* g_bar, int gridSize, unsigned int& local_sense) {
    __syncthreads();
    if (threadIdx.x == 0) {
        __threadfence();
        unsigned int old = atomicInc(&g_bar[0], (unsigned int)(gridSize - 1));
        if (old == (unsigned int)(gridSize - 1)) {
            // last arriver: counter auto-wrapped to 0 by atomicInc; flip sense.
            __threadfence();
            atomicXor(&g_bar[1], 1u);
        } else {
            while (((volatile unsigned int*)g_bar)[1] == local_sense) { }
        }
        __threadfence();
    }
    __syncthreads();
    local_sense ^= 1u;
}

// Factor + build-T for one panel, executed by BLOCK 0 only. The ACTIVE sub-panel
// (rows [p,n) x nb columns) is loaded into shared memory and factored ON-CHIP
// (the single-block-over-global panel was the dominant bottleneck); reflectors +
// R diag are written back to global Acm. T (compact WY) is built in smem and
// written to Tg. dsmem layout: Ps[(r-p) + j*ldp] holds the sub-panel, ldp=n-p.
template <int TPB, int NBMAX>
__device__ void coop_panel_factor(float* __restrict__ Acm, float* __restrict__ Tg,
                                  float* __restrict__ taub, float* dsmem,
                                  int n, int p, int nb) {
    const int NWARP = TPB / 32;
    const int REDSZ = (NBMAX * NWARP > TPB) ? NBMAX * NWARP : TPB;
    __shared__ float red[REDSZ];
    __shared__ float sval[4];
    __shared__ float zsh[NBMAX];
    __shared__ float taus[NBMAX];
    const int tid = threadIdx.x;
    const int lane = tid & 31, warp = tid >> 5;
    const int ldp = n - p;                 // sub-panel leading dimension (rows)
    float* Ps = dsmem;                     // ldp * nb  (col-major: Ps[rr + j*ldp])

    // load active sub-panel rows [p,n) of cols [p,p+nb) into smem
    for (int idx = tid; idx < ldp * nb; idx += TPB) {
        int j = idx / ldp, rr = idx % ldp;
        Ps[rr + j * ldp] = Acm[(size_t)(p + j) * n + (p + rr)];
    }
    __syncthreads();

    for (int j = 0; j < nb; ++j) {
        float* pj = Ps + (size_t)j * ldp;  // panel column j (smem); local row rj=j
        int rj = j;                        // diagonal local row for this column
        // --- column norm over local rows >= rj ---
        float partial = 0.f;
        for (int rr = rj + tid; rr < ldp; rr += TPB) { float x = pj[rr]; partial += x * x; }
        red[tid] = partial; __syncthreads();
        for (int s = TPB / 2; s > 0; s >>= 1) { if (tid < s) red[tid] += red[tid + s]; __syncthreads(); }
        if (tid == 0) {
            float xnorm = sqrtf(red[0]);
            float alpha = pj[rj];
            float beta = (alpha >= 0.f) ? -xnorm : xnorm;
            float tval, invden;
            if (xnorm > 0.f && (alpha - beta) != 0.f) {
                tval = (beta - alpha) / beta; invden = 1.f / (alpha - beta);
            } else { tval = 0.f; invden = 0.f; beta = alpha; }
            sval[0] = beta; sval[1] = tval; sval[2] = invden;
        }
        __syncthreads();
        float beta = sval[0], tval = sval[1], invden = sval[2];
        for (int rr = rj + 1 + tid; rr < ldp; rr += TPB) pj[rr] *= invden;
        __syncthreads();
        if (tid == 0) { pj[rj] = 1.f; taus[j] = tval; }
        __syncthreads();
        int ntrail = nb - (j + 1);
        if (ntrail > 0) {
            float pw[NBMAX];
            #pragma unroll
            for (int t = 0; t < NBMAX; ++t) pw[t] = 0.f;
            for (int rr = rj + tid; rr < ldp; rr += TPB) {
                float vr = pj[rr];
                for (int t = 0; t < ntrail; ++t)
                    pw[t] += vr * Ps[(size_t)(j + 1 + t) * ldp + rr];
            }
            for (int t = 0; t < ntrail; ++t) {
                float v = pw[t];
                #pragma unroll
                for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
                if (lane == 0) red[t * NWARP + warp] = v;
            }
            __syncthreads();
            if (tid < ntrail) {
                float w = 0.f;
                for (int wi = 0; wi < NWARP; ++wi) w += red[tid * NWARP + wi];
                zsh[tid] = tval * w;
            }
            __syncthreads();
            for (int t = 0; t < ntrail; ++t) {
                float tw = zsh[t];
                float* pjj = Ps + (size_t)(j + 1 + t) * ldp;
                for (int rr = rj + tid; rr < ldp; rr += TPB) pjj[rr] -= tw * pj[rr];
            }
            __syncthreads();
        }
        if (tid == 0) pj[rj] = beta;       // R diagonal
        __syncthreads();
    }
    // ---- build T (compact WY) from smem panel, Tg col-major Tg[i + l*NBMAX] ----
    for (int i = tid; i < nb; i += TPB) { Tg[(size_t)i + (size_t)i * NBMAX] = taus[i]; taub[p + i] = taus[i]; }
    __syncthreads();
    for (int l = 1; l < nb; ++l) {
        const float* Vl = Ps + (size_t)l * ldp;     // V column l (local diag row l = beta -> treat as 1)
        float pz[NBMAX];
        #pragma unroll
        for (int t = 0; t < NBMAX; ++t) pz[t] = 0.f;
        for (int rr = l + tid; rr < ldp; rr += TPB) {
            float vl = (rr == l) ? 1.f : Vl[rr];
            for (int i = 0; i < l; ++i) {
                const float* Vi = Ps + (size_t)i * ldp;
                float vi = (rr == i) ? 1.f : Vi[rr];
                pz[i] += vi * vl;
            }
        }
        for (int i = 0; i < l; ++i) {
            float v = pz[i];
            #pragma unroll
            for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
            if (lane == 0) red[i * NWARP + warp] = v;
        }
        __syncthreads();
        if (tid < l) {
            float zz = 0.f;
            for (int wi = 0; wi < NWARP; ++wi) zz += red[tid * NWARP + wi];
            zsh[tid] = zz;
        }
        __syncthreads();
        float tl = taus[l];
        for (int i = tid; i < l; i += TPB) {
            float acc = 0.f;
            for (int m = i; m < l; ++m) acc += Tg[(size_t)i + (size_t)m * NBMAX] * zsh[m];
            Tg[(size_t)i + (size_t)l * NBMAX] = -tl * acc;
        }
        __syncthreads();
    }
    // ---- write factored sub-panel back to global Acm (rows [p,n), cols [p,p+nb)) ----
    for (int idx = tid; idx < ldp * nb; idx += TPB) {
        int j = idx / ldp, rr = idx % ldp;
        Acm[(size_t)(p + j) * n + (p + rr)] = Ps[rr + j * ldp];
    }
    __syncthreads();
}

// Apply block reflector to the trailing submatrix. Every CTA grid-strides over
// COLUMN TILES of width CT; within a tile it does the WY update as two row-tiled
// GEMMs (V staged through smem in row strips of RB):
//   pass 1:  W  = V^T C          (W is nb x CT, accumulated across strips)
//            W' = T^T W
//   pass 2:  C -= V W'
// V = Acm[:, p:p+nb] (implicit unit diag, V[p+i,i]=1, zero above), rows >= p.
// CT trailing columns of C stay in global (read once in pass 1, read+written in
// pass 2). T (nb x nb upper-tri) and W/W' (nb x CT) live in smem.
template <int TPB, int NBMAX, int CT, int RB>
__device__ void coop_trailing_update(float* __restrict__ Acm, const float* __restrict__ Tg,
                                     float* dsmem, int n, int p, int nb) {
    const int tid = threadIdx.x;
    // partition dynamic smem
    float* Ts  = dsmem;                       // nb*nb   (col-major: Ts[l + i*nb])
    float* Ws  = Ts + (size_t)NBMAX * NBMAX;  // nb*CT   (col-major: Ws[i + g*nb])
    float* Wps = Ws + (size_t)NBMAX * CT;     // nb*CT   (col-major: Wps[i + g*nb])
    float* Vs  = Wps + (size_t)NBMAX * CT;    // RB*nb   (col-major: Vs[rr + i*RB])
    // cache T
    for (int idx = tid; idx < nb * nb; idx += TPB) Ts[idx] = Tg[idx % nb + (idx / nb) * NBMAX];
    __syncthreads();

    const int tstart = p + nb;
    for (int g0 = tstart + blockIdx.x * CT; g0 < n; g0 += gridDim.x * CT) {
        int ct = CT; if (g0 + ct > n) ct = n - g0;

        // ---- pass 1: W[i,g] = sum_{r>=p} V[r,i] C[r,g] ----
        for (int idx = tid; idx < nb * ct; idx += TPB) Ws[idx] = 0.f;
        __syncthreads();
        for (int r0 = p; r0 < n; r0 += RB) {
            int rb = RB; if (r0 + rb > n) rb = n - r0;
            // load V strip Vs[rr, i] = V[r0+rr, i]  (unit diag, zero above diag)
            for (int idx = tid; idx < rb * nb; idx += TPB) {
                int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = p + i;
                float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
                Vs[rr + i * RB] = vv;
            }
            __syncthreads();
            // each thread owns (i,g) pairs; accumulate over the strip's rows.
            for (int idx = tid; idx < nb * ct; idx += TPB) {
                int g = idx / nb, i = idx % nb;
                const float* Cg = Acm + (size_t)(g0 + g) * n;
                float acc = 0.f;
                for (int rr = 0; rr < rb; ++rr) acc += Vs[rr + i * RB] * Cg[r0 + rr];
                Ws[i + g * nb] += acc;
            }
            __syncthreads();
        }
        // ---- W' = T^T W :  W'[i,g] = sum_{l<=i} T[l,i] W[l,g]  (double-buffered) ----
        // negate W' so pass 2 does C += V*W'  (== C -= V W').
        for (int idx = tid; idx < nb * ct; idx += TPB) {
            int g = idx / nb, i = idx % nb;
            float acc = 0.f;
            for (int l = 0; l <= i; ++l) acc += Ts[l + i * nb] * Ws[l + g * nb];
            Wps[i + g * nb] = -acc;
        }
        __syncthreads();
        // ---- pass 2: C[r,g] += V[r,i] * W'[i,g] ----
        for (int r0 = p; r0 < n; r0 += RB) {
            int rb = RB; if (r0 + rb > n) rb = n - r0;
            for (int idx = tid; idx < rb * nb; idx += TPB) {
                int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = p + i;
                float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
                Vs[rr + i * RB] = vv;
            }
            __syncthreads();
            for (int idx = tid; idx < rb * ct; idx += TPB) {
                int g = idx / rb, rr = idx % rb, r = r0 + rr;
                float* Cg = Acm + (size_t)(g0 + g) * n;
                float acc = 0.f;
                int imax = r - p; if (imax >= nb) imax = nb - 1;
                for (int i = 0; i <= imax; ++i) acc += Vs[rr + i * RB] * Wps[i + g * nb];
                Cg[r] += acc;
            }
            __syncthreads();
        }
    }
}

template <int TPB, int NBMAX, int CT, int RB>
__global__ void qr_coop_kernel(const float* __restrict__ A, float* __restrict__ Acm,
                               float* __restrict__ H, float* __restrict__ tau,
                               float* __restrict__ Tg, unsigned int* __restrict__ g_bar,
                               int n, int gridSize) {
    extern __shared__ float dsmem[];
    const int tid = threadIdx.x;
    const int gtid = blockIdx.x * TPB + tid;
    const int gstride = gridDim.x * TPB;
    unsigned int sense = 0u;

    // row-major A -> column-major Acm (all CTAs)
    for (size_t idx = gtid; idx < (size_t)n * n; idx += gstride) {
        int r = idx / n, c = idx % n;
        Acm[(size_t)c * n + r] = A[(size_t)r * n + c];
    }
    coop_grid_barrier(g_bar, gridSize, sense);

    for (int p = 0; p < n; p += NBMAX) {
        int nb = NBMAX; if (p + nb > n) nb = n - p;
        if (blockIdx.x == 0) coop_panel_factor<TPB, NBMAX>(Acm, Tg, tau, dsmem, n, p, nb);
        coop_grid_barrier(g_bar, gridSize, sense);
        coop_trailing_update<TPB, NBMAX, CT, RB>(Acm, Tg, dsmem, n, p, nb);
        coop_grid_barrier(g_bar, gridSize, sense);
    }

    // column-major Acm -> row-major H (all CTAs)
    for (size_t idx = gtid; idx < (size_t)n * n; idx += gstride) {
        int r = idx / n, c = idx % n;
        H[(size_t)r * n + c] = Acm[(size_t)c * n + r];
    }
}

template <int NBMAX, int CT, int RB>
static size_t coop_smem_bytes(int n) {
    // dynamic smem must cover BOTH the panel sub-panel (rows[p,n) x NBMAX, max at
    // p=0 -> n*NBMAX) and the trailing-update buffers.
    size_t panel = (size_t)n * NBMAX;
    size_t trail = (size_t)NBMAX * NBMAX + 2 * (size_t)NBMAX * CT + (size_t)RB * NBMAX;
    size_t fcount = panel > trail ? panel : trail;
    return fcount * sizeof(float);
}

template <int TPB, int NBMAX, int CT, int RB>
static int coop_max_grid(size_t sh) {
    int blocks = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks, qr_coop_kernel<TPB, NBMAX, CT, RB>, TPB, sh);
    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
    return blocks * sms;
}

template <int TPB, int NBMAX, int CT, int RB>
static void coop_dispatch(const float* A, float* Acm, float* H, float* tau, float* Tg,
                          unsigned int* g_bar, int n, int gridcap) {
    size_t sh = coop_smem_bytes<NBMAX, CT, RB>(n);
    cudaFuncSetAttribute(qr_coop_kernel<TPB, NBMAX, CT, RB>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize, (int)sh);
    int maxg = coop_max_grid<TPB, NBMAX, CT, RB>(sh);
    int grid = maxg; if (gridcap > 0 && gridcap < grid) grid = gridcap;
    if (grid < 1) grid = 1;
    qr_coop_kernel<TPB, NBMAX, CT, RB><<<grid, TPB, sh>>>(A, Acm, H, tau, Tg, g_bar, n, grid);
}

void qr_coop_launch(int64_t A_ptr, int64_t Acm_ptr, int64_t H_ptr, int64_t tau_ptr,
                    int64_t Tg_ptr, int64_t gbar_ptr, int n, int NB, int gridcap) {
    const float* A = reinterpret_cast<const float*>(A_ptr);
    float* Acm = reinterpret_cast<float*>(Acm_ptr);
    float* H = reinterpret_cast<float*>(H_ptr);
    float* tau = reinterpret_cast<float*>(tau_ptr);
    float* Tg = reinterpret_cast<float*>(Tg_ptr);
    unsigned int* g_bar = reinterpret_cast<unsigned int*>(gbar_ptr);
    const int TPB = 256;
    const int CT = 32;       // trailing column-tile width per CTA
    const int RB = 64;       // V row-strip height staged through smem
    switch (NB) {
        case 8:  coop_dispatch<TPB, 8,  CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
        case 16: coop_dispatch<TPB, 16, CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
        case 24: coop_dispatch<TPB, 24, CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
        case 32: coop_dispatch<TPB, 32, CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
        default: coop_dispatch<TPB, 16, CT, RB>(A, Acm, H, tau, Tg, g_bar, n, gridcap); break;
    }
}

// ===========================================================================
// BATCHED TWO-KERNEL blocked QR for large n (n>1024), small batch B.
//   The grid-barrier megakernel above is occupancy-limited to 12.5% because its
//   per-block smem = n*NB (panel sub-panel) forces 1 block/SM EVEN for the
//   trailing update (the dominant work). This version splits panel factor and
//   trailing update into SEPARATE kernel launches (the launch boundary is the
//   barrier -- NO cross-CTA atomics needed, capturable). The trailing kernel
//   uses a tiny smem footprint -> high occupancy + a large grid; the panel
//   kernel runs B blocks (one per matrix), so its big smem only costs B SMs.
//   All B matrices are factored CONCURRENTLY (panel kernel = B blocks; trailing
//   kernel grid-strides over (matrix, column-tile) work items).
// Acm: column-major B*n*n. Tg: B*NBMAX*NBMAX compact-WY T. tau: B*n.
// ===========================================================================

// transpose row-major A (B,n,n) -> column-major Acm (per matrix Acm[b][c*n+r]).
__global__ void qr_transpose_in(const float* __restrict__ A, float* __restrict__ Acm,
                                int B, int n) {
    const size_t total = (size_t)B * n * n;
    for (size_t idx = (size_t)blockIdx.x * blockDim.x + threadIdx.x; idx < total;
         idx += (size_t)gridDim.x * blockDim.x) {
        int b = idx / ((size_t)n * n);
        size_t rem = idx - (size_t)b * n * n;
        int r = rem / n, c = rem % n;
        Acm[(size_t)b * n * n + (size_t)c * n + r] = A[(size_t)b * n * n + (size_t)r * n + c];
    }
}
__global__ void qr_transpose_out(const float* __restrict__ Acm, float* __restrict__ H,
                                 int B, int n) {
    const size_t total = (size_t)B * n * n;
    for (size_t idx = (size_t)blockIdx.x * blockDim.x + threadIdx.x; idx < total;
         idx += (size_t)gridDim.x * blockDim.x) {
        int b = idx / ((size_t)n * n);
        size_t rem = idx - (size_t)b * n * n;
        int r = rem / n, c = rem % n;
        H[(size_t)b * n * n + (size_t)r * n + c] = Acm[(size_t)b * n * n + (size_t)c * n + r];
    }
}

// PANEL FACTOR kernel: grid = B (block b factors matrix b's panel [p,p+nb)).
// Active sub-panel rows[p,n) x nb loaded into dynamic smem (ldp*nb floats,
// sized by the host for this p), factored on-chip; reflectors+R written back to
// Acm[b]; compact-WY T built into Tg[b]. Identical math to coop_panel_factor.
template <int TPB, int NBMAX>
__global__ void qr_panel_kernel(float* __restrict__ Acm_all, float* __restrict__ Tg_all,
                                float* __restrict__ tau_all, int B, int n, int p, int nb) {
    extern __shared__ float Ps[];          // ldp * nb (col-major Ps[rr + j*ldp])
    const int b = blockIdx.x;
    if (b >= B) return;
    float* Acm = Acm_all + (size_t)b * n * n;
    float* Tg  = Tg_all + (size_t)b * NBMAX * NBMAX;
    float* taub = tau_all + (size_t)b * n;

    const int NWARP = TPB / 32;
    const int REDSZ = (NBMAX * NWARP > TPB) ? NBMAX * NWARP : TPB;
    __shared__ float red[REDSZ];
    __shared__ float sval[4];
    __shared__ float zsh[NBMAX];
    __shared__ float taus[NBMAX];
    const int tid = threadIdx.x;
    const int lane = tid & 31, warp = tid >> 5;
    const int ldp = n - p;

    for (int idx = tid; idx < ldp * nb; idx += TPB) {
        int j = idx / ldp, rr = idx % ldp;
        Ps[rr + j * ldp] = Acm[(size_t)(p + j) * n + (p + rr)];
    }
    __syncthreads();

    for (int j = 0; j < nb; ++j) {
        float* pj = Ps + (size_t)j * ldp;
        int rj = j;
        float partial = 0.f;
        for (int rr = rj + tid; rr < ldp; rr += TPB) { float x = pj[rr]; partial += x * x; }
        red[tid] = partial; __syncthreads();
        for (int s = TPB / 2; s > 0; s >>= 1) { if (tid < s) red[tid] += red[tid + s]; __syncthreads(); }
        if (tid == 0) {
            float xnorm = sqrtf(red[0]);
            float alpha = pj[rj];
            float beta = (alpha >= 0.f) ? -xnorm : xnorm;
            float tval, invden;
            if (xnorm > 0.f && (alpha - beta) != 0.f) {
                tval = (beta - alpha) / beta; invden = 1.f / (alpha - beta);
            } else { tval = 0.f; invden = 0.f; beta = alpha; }
            sval[0] = beta; sval[1] = tval; sval[2] = invden;
        }
        __syncthreads();
        float beta = sval[0], tval = sval[1], invden = sval[2];
        for (int rr = rj + 1 + tid; rr < ldp; rr += TPB) pj[rr] *= invden;
        __syncthreads();
        if (tid == 0) { pj[rj] = 1.f; taus[j] = tval; }
        __syncthreads();
        int ntrail = nb - (j + 1);
        if (ntrail > 0) {
            float pw[NBMAX];
            #pragma unroll
            for (int t = 0; t < NBMAX; ++t) pw[t] = 0.f;
            for (int rr = rj + tid; rr < ldp; rr += TPB) {
                float vr = pj[rr];
                for (int t = 0; t < ntrail; ++t)
                    pw[t] += vr * Ps[(size_t)(j + 1 + t) * ldp + rr];
            }
            for (int t = 0; t < ntrail; ++t) {
                float v = pw[t];
                #pragma unroll
                for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
                if (lane == 0) red[t * NWARP + warp] = v;
            }
            __syncthreads();
            if (tid < ntrail) {
                float w = 0.f;
                for (int wi = 0; wi < NWARP; ++wi) w += red[tid * NWARP + wi];
                zsh[tid] = tval * w;
            }
            __syncthreads();
            for (int t = 0; t < ntrail; ++t) {
                float tw = zsh[t];
                float* pjj = Ps + (size_t)(j + 1 + t) * ldp;
                for (int rr = rj + tid; rr < ldp; rr += TPB) pjj[rr] -= tw * pj[rr];
            }
            __syncthreads();
        }
        if (tid == 0) pj[rj] = beta;
        __syncthreads();
    }
    for (int i = tid; i < nb; i += TPB) { Tg[(size_t)i + (size_t)i * NBMAX] = taus[i]; taub[p + i] = taus[i]; }
    __syncthreads();
    for (int l = 1; l < nb; ++l) {
        const float* Vl = Ps + (size_t)l * ldp;
        float pz[NBMAX];
        #pragma unroll
        for (int t = 0; t < NBMAX; ++t) pz[t] = 0.f;
        for (int rr = l + tid; rr < ldp; rr += TPB) {
            float vl = (rr == l) ? 1.f : Vl[rr];
            for (int i = 0; i < l; ++i) {
                const float* Vi = Ps + (size_t)i * ldp;
                float vi = (rr == i) ? 1.f : Vi[rr];
                pz[i] += vi * vl;
            }
        }
        for (int i = 0; i < l; ++i) {
            float v = pz[i];
            #pragma unroll
            for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
            if (lane == 0) red[i * NWARP + warp] = v;
        }
        __syncthreads();
        if (tid < l) {
            float zz = 0.f;
            for (int wi = 0; wi < NWARP; ++wi) zz += red[tid * NWARP + wi];
            zsh[tid] = zz;
        }
        __syncthreads();
        float tl = taus[l];
        for (int i = tid; i < l; i += TPB) {
            float acc = 0.f;
            for (int m = i; m < l; ++m) acc += Tg[(size_t)i + (size_t)m * NBMAX] * zsh[m];
            Tg[(size_t)i + (size_t)l * NBMAX] = -tl * acc;
        }
        __syncthreads();
    }
    for (int idx = tid; idx < ldp * nb; idx += TPB) {
        int j = idx / ldp, rr = idx % ldp;
        Acm[(size_t)(p + j) * n + (p + rr)] = Ps[rr + j * ldp];
    }
}

// TRAILING kernel: grid-strides over (matrix b, column-tile g0) work items.
// Small smem (Ts + Ws + Wps + Vs) -> high occupancy, large grid. For each work
// item applies the block reflector to CT trailing columns of matrix b:
//   W = V^T C ; W' = T^T W ; C -= V W'  (V staged through smem in RB-row strips).
template <int TPB, int NBMAX, int CT, int RB>
__global__ void qr_trailing_kernel(float* __restrict__ Acm_all, const float* __restrict__ Tg_all,
                                   int B, int n, int p, int nb) {
    extern __shared__ float dsmem[];
    float* Ts  = dsmem;                       // nb*nb
    float* Ws  = Ts + (size_t)NBMAX * NBMAX;  // nb*CT
    float* Wps = Ws + (size_t)NBMAX * CT;     // nb*CT
    float* Vs  = Wps + (size_t)NBMAX * CT;    // RB*nb
    float* Cs  = Vs + (size_t)RB * NBMAX;     // RB*CT (C strip, col-major Cs[rr+g*RB])
    const int tid = threadIdx.x;

    const int tstart = p + nb;
    const int ntiles = (n - tstart + CT - 1) / CT;   // column tiles per matrix
    if (ntiles <= 0) return;
    const long totwork = (long)B * ntiles;

    for (long widx = blockIdx.x; widx < totwork; widx += gridDim.x) {
        int b = widx / ntiles;
        int tileIdx = widx - (long)b * ntiles;
        int g0 = tstart + tileIdx * CT;
        int ct = CT; if (g0 + ct > n) ct = n - g0;
        float* Acm = Acm_all + (size_t)b * n * n;
        const float* Tg = Tg_all + (size_t)b * NBMAX * NBMAX;

        // cache T for this matrix
        for (int idx = tid; idx < nb * nb; idx += TPB) Ts[idx] = Tg[idx % nb + (idx / nb) * NBMAX];
        __syncthreads();

        // pass 1: W = V^T C. Stage BOTH V and C strips into smem so each C
        // element is read from global ONCE per strip (was read nb times).
        for (int idx = tid; idx < nb * ct; idx += TPB) Ws[idx] = 0.f;
        __syncthreads();
        for (int r0 = p; r0 < n; r0 += RB) {
            int rb = RB; if (r0 + rb > n) rb = n - r0;
            for (int idx = tid; idx < rb * nb; idx += TPB) {
                int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = p + i;
                float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
                Vs[rr + i * RB] = vv;
            }
            for (int idx = tid; idx < rb * ct; idx += TPB) {
                int g = idx / rb, rr = idx % rb;
                Cs[rr + g * RB] = Acm[(size_t)(g0 + g) * n + (r0 + rr)];
            }
            __syncthreads();
            for (int idx = tid; idx < nb * ct; idx += TPB) {
                int g = idx / nb, i = idx % nb;
                float acc = 0.f;
                for (int rr = 0; rr < rb; ++rr) acc += Vs[rr + i * RB] * Cs[rr + g * RB];
                Ws[i + g * nb] += acc;
            }
            __syncthreads();
        }
        // W' = -T^T W
        for (int idx = tid; idx < nb * ct; idx += TPB) {
            int g = idx / nb, i = idx % nb;
            float acc = 0.f;
            for (int l = 0; l <= i; ++l) acc += Ts[l + i * nb] * Ws[l + g * nb];
            Wps[i + g * nb] = -acc;
        }
        __syncthreads();
        // pass 2: C += V W'
        for (int r0 = p; r0 < n; r0 += RB) {
            int rb = RB; if (r0 + rb > n) rb = n - r0;
            for (int idx = tid; idx < rb * nb; idx += TPB) {
                int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = p + i;
                float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
                Vs[rr + i * RB] = vv;
            }
            __syncthreads();
            for (int idx = tid; idx < rb * ct; idx += TPB) {
                int g = idx / rb, rr = idx % rb, r = r0 + rr;
                float* Cg = Acm + (size_t)(g0 + g) * n;
                float acc = 0.f;
                int imax = r - p; if (imax >= nb) imax = nb - 1;
                for (int i = 0; i <= imax; ++i) acc += Vs[rr + i * RB] * Wps[i + g * nb];
                Cg[r] += acc;
            }
            __syncthreads();
        }
    }
}

template <int TPB, int NBMAX, int CT, int RB>
static int trailing_max_grid(size_t sh) {
    int blocks = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks, qr_trailing_kernel<TPB, NBMAX, CT, RB>, TPB, sh);
    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
    return blocks * sms;
}

template <int TPB, int NBMAX, int CT, int RB>
static void coop2_run(float* Acm, float* Tg, float* tau, int B, int n) {
    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
    // trailing kernel smem: Ts + Ws + Wps + Vs + Cs (C strip staged for pass1).
    size_t trail_sh = ((size_t)NBMAX * NBMAX + 2 * (size_t)NBMAX * CT
                       + (size_t)RB * NBMAX + (size_t)RB * CT) * sizeof(float);
    int tgrid = trailing_max_grid<TPB, NBMAX, CT, RB>(trail_sh);
    if (tgrid < 1) tgrid = sms;
    // panel kernel: dynamic smem ldp*nb (sized per p); cap to device opt-in.
    cudaFuncSetAttribute(qr_panel_kernel<TPB, NBMAX>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize, (int)((size_t)n * NBMAX * sizeof(float)));
    for (int p = 0; p < n; p += NBMAX) {
        int nb = NBMAX; if (p + nb > n) nb = n - p;
        size_t panel_sh = (size_t)(n - p) * nb * sizeof(float);
        qr_panel_kernel<TPB, NBMAX><<<B, TPB, panel_sh>>>(Acm, Tg, tau, B, n, p, nb);
        if (p + nb < n)
            qr_trailing_kernel<TPB, NBMAX, CT, RB><<<tgrid, TPB, trail_sh>>>(Acm, Tg, B, n, p, nb);
    }
}

// driver: A(row-major) -> Acm(col-major) -> factor -> H(row-major).
template <int TPB, int NBMAX, int CT, int RB>
static void coop2_dispatch(const float* A, float* Acm, float* H, float* tau, float* Tg,
                           int B, int n) {
    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
    int cgrid = sms * 4;
    qr_transpose_in<<<cgrid, TPB>>>(A, Acm, B, n);
    coop2_run<TPB, NBMAX, CT, RB>(Acm, Tg, tau, B, n);
    qr_transpose_out<<<cgrid, TPB>>>(Acm, H, B, n);
}

void qr_coop2_launch(int64_t A_ptr, int64_t Acm_ptr, int64_t H_ptr, int64_t tau_ptr,
                     int64_t Tg_ptr, int B, int n, int NB) {
    const float* A = reinterpret_cast<const float*>(A_ptr);
    float* Acm = reinterpret_cast<float*>(Acm_ptr);
    float* H = reinterpret_cast<float*>(H_ptr);
    float* tau = reinterpret_cast<float*>(tau_ptr);
    float* Tg = reinterpret_cast<float*>(Tg_ptr);
    const int TPB = 256;
    const int CT = 32;
    const int RB = 64;
    switch (NB) {
        case 8:  coop2_dispatch<TPB, 8,  CT, RB>(A, Acm, H, tau, Tg, B, n); break;
        case 16: coop2_dispatch<TPB, 16, CT, RB>(A, Acm, H, tau, Tg, B, n); break;
        case 24: coop2_dispatch<TPB, 24, CT, RB>(A, Acm, H, tau, Tg, B, n); break;
        case 32: coop2_dispatch<TPB, 32, CT, RB>(A, Acm, H, tau, Tg, B, n); break;
        default: coop2_dispatch<TPB, 16, CT, RB>(A, Acm, H, tau, Tg, B, n); break;
    }
}

// ===========================================================================
// TWO-LEVEL panel for the batched scheme: factor a WIDE panel of width NB using
// inner sub-blocks of width IB (each held in smem at (n-ps)*IB, which fits even
// when (n-p)*NB would not). This decouples the trailing block width NB (which we
// want LARGE -> the trailing update re-reads C n/NB times, so HBM traffic ~1/NB)
// from the smem limit. The panel kernel still runs B blocks, so its cost is on
// B SMs; the wide T is built from the global reflectors. The same trailing
// kernel then runs with the large NB.
// ===========================================================================

// Factor inner sub-block [ps,ps+ib) (cols local 0..ib-1) of matrix Acm, holding
// rows[ps,n) x ib in smem Ps; write reflectors+R back to Acm; fill the IB-block
// diagonal of the wide T (Tg col-major, NBMAX-leading) at columns [ps-p..].
template <int TPB, int IB, int NBMAX>
__device__ void wpanel_inner_factor(float* __restrict__ Acm, float* __restrict__ Tg,
                                    float* __restrict__ taub, float* Ps,
                                    float* red, float* sval, float* zsh, float* taus,
                                    int n, int p, int ps, int ib) {
    const int NWARP = TPB / 32;
    const int tid = threadIdx.x;
    const int lane = tid & 31, warp = tid >> 5;
    const int ldp = n - ps;
    for (int idx = tid; idx < ldp * ib; idx += TPB) {
        int j = idx / ldp, rr = idx % ldp;
        Ps[rr + j * ldp] = Acm[(size_t)(ps + j) * n + (ps + rr)];
    }
    __syncthreads();
    for (int j = 0; j < ib; ++j) {
        float* pj = Ps + (size_t)j * ldp;
        int rj = j;
        float partial = 0.f;
        for (int rr = rj + tid; rr < ldp; rr += TPB) { float x = pj[rr]; partial += x * x; }
        red[tid] = partial; __syncthreads();
        for (int s = TPB / 2; s > 0; s >>= 1) { if (tid < s) red[tid] += red[tid + s]; __syncthreads(); }
        if (tid == 0) {
            float xnorm = sqrtf(red[0]);
            float alpha = pj[rj];
            float beta = (alpha >= 0.f) ? -xnorm : xnorm;
            float tval, invden;
            if (xnorm > 0.f && (alpha - beta) != 0.f) { tval = (beta - alpha) / beta; invden = 1.f / (alpha - beta); }
            else { tval = 0.f; invden = 0.f; beta = alpha; }
            sval[0] = beta; sval[1] = tval; sval[2] = invden;
        }
        __syncthreads();
        float beta = sval[0], tval = sval[1], invden = sval[2];
        for (int rr = rj + 1 + tid; rr < ldp; rr += TPB) pj[rr] *= invden;
        __syncthreads();
        if (tid == 0) { pj[rj] = 1.f; taus[j] = tval; }
        __syncthreads();
        int ntrail = ib - (j + 1);
        if (ntrail > 0) {
            float pw[IB];
            #pragma unroll
            for (int t = 0; t < IB; ++t) pw[t] = 0.f;
            for (int rr = rj + tid; rr < ldp; rr += TPB) {
                float vr = pj[rr];
                for (int t = 0; t < ntrail; ++t) pw[t] += vr * Ps[(size_t)(j + 1 + t) * ldp + rr];
            }
            for (int t = 0; t < ntrail; ++t) {
                float v = pw[t];
                #pragma unroll
                for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
                if (lane == 0) red[t * NWARP + warp] = v;
            }
            __syncthreads();
            if (tid < ntrail) { float w = 0.f; for (int wi = 0; wi < NWARP; ++wi) w += red[tid * NWARP + wi]; zsh[tid] = tval * w; }
            __syncthreads();
            for (int t = 0; t < ntrail; ++t) {
                float tw = zsh[t];
                float* pjj = Ps + (size_t)(j + 1 + t) * ldp;
                for (int rr = rj + tid; rr < ldp; rr += TPB) pjj[rr] -= tw * pj[rr];
            }
            __syncthreads();
        }
        if (tid == 0) pj[rj] = beta;
        __syncthreads();
    }
    // diagonal IB-block of wide T (recurrence within the inner block, V from smem)
    int co = ps - p;     // wide-column offset of this inner block
    for (int i = tid; i < ib; i += TPB) { Tg[(size_t)(co + i) + (size_t)(co + i) * NBMAX] = taus[i]; taub[ps + i] = taus[i]; }
    __syncthreads();
    for (int l = 1; l < ib; ++l) {
        const float* Vl = Ps + (size_t)l * ldp;
        float pz[IB];
        #pragma unroll
        for (int t = 0; t < IB; ++t) pz[t] = 0.f;
        for (int rr = l + tid; rr < ldp; rr += TPB) {
            float vl = (rr == l) ? 1.f : Vl[rr];
            for (int i = 0; i < l; ++i) { const float* Vi = Ps + (size_t)i * ldp; float vi = (rr == i) ? 1.f : Vi[rr]; pz[i] += vi * vl; }
        }
