# Compile the CUDA extension eagerly at import so build-time surfaces errors.
_get_cuda_mod()


def custom_kernel(data: input_t) -> output_t:
    a = data
    n = a.shape[-1]
    if n <= 64:
        return _qr_triton(a.contiguous())
    # The blocked compact-WY megakernel (batched panel/T-build reductions)
    # beats the full-matrix-in-smem kernel even at small n that fits smem,
    # so route everything n=65..1024 through it.
    if n < 352:
        return _qr_cuda_blocked(a.contiguous(), 5)  # NB16 CT128 (small n: blocked wins)
    # n >= 352: batched two-kernel blocked QR with a TENSOR-CORE (tf32x3)
    # trailing update. The trailing block-reflector GEMM was 85% of GPU time as
    # an FP32-SIMT ~1 TFLOP/s kernel; tf32x3 tl.dot runs it on tensor cores at
    # ~FP32 accuracy. nb=16 keeps the CUDA panel sub-panel in smem (ldp*16*4 <=
    # 227KB for n<=2048) and gives the apply MMA a valid K=16.
    if n <= 1024:
        # Transpose-free row-major path: drops both transpose kernels (~18%).
        # Wins at n<=1024; at n=2048 the row-major strided panel loads coalesce
        # worse than the column-major scratch, so n=2048 keeps the CM path.
        return _qr_cuda_coop2_tc_rm(a.contiguous(), nb=16)
    if n <= 2048:
        return _qr_cuda_coop2_tc(a.contiguous(), nb=16)
    # n=4096: flat (n-p)*16 panel overflows smem (256KB); use the two-level IB=8
    # wide-panel factor (smem (n-p)*8 = 128KB) feeding the same tf32x3 trailing.
    return _qr_cuda_coop2_tc(a.contiguous(), nb=16, wide=True)

